LocalDate fecha = LocalDate.of(2026, 10, 5);

DateTimeFormatter.ofLocalizedDate(FormatStyle.LONG).withLocale(Locale.US).format(fecha);      // October 5, 2026
DateTimeFormatter.ofLocalizedDate(FormatStyle.LONG).withLocale(Locale.GERMANY).format(fecha); // 5. Oktober 2026

DateTimeFormatter fmt = DateTimeFormatter.ofPattern("d 'de' MMMM 'de' yyyy", Locale.of("es", "CL"));
String texto = fecha.format(fmt);
LocalDate.parse(texto, fmt).equals(fecha); // true -- mismo formatter para format() y parse()

exercises.code:
LocalDate fecha = LocalDate.of(2026, 10, 5);
LocalTime hora = LocalTime.of(14, 30);

DateTimeFormatter fechaUS = DateTimeFormatter.ofLocalizedDate(FormatStyle.LONG).withLocale(Locale.US);
DateTimeFormatter fechaDE = DateTimeFormatter.ofLocalizedDate(FormatStyle.LONG).withLocale(Locale.GERMANY);
System.out.println(fecha.format(fechaUS)); // October 5, 2026 (mes primero, en ingles)
System.out.println(fecha.format(fechaDE)); // 5. Oktober 2026 (dia primero, en aleman)

DateTimeFormatter horaUS = DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT).withLocale(Locale.US);
DateTimeFormatter horaDE = DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT).withLocale(Locale.GERMANY);
System.out.println(hora.format(horaUS)); // formato de 12 horas, con marcador AM/PM
System.out.println(hora.format(horaDE)); // 14:30 (formato de 24 horas, sin marcador)

DateTimeFormatter fechaUSCorta = DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT).withLocale(Locale.US);
System.out.println(fecha.format(fechaUSCorta)); // 10/5/26 (mismo Locale.US que fechaUS, pero con FormatStyle.SHORT en vez de LONG)

LocalDate fecha = LocalDate.of(2026, 10, 5);
DateTimeFormatter us = DateTimeFormatter.ofPattern("MMMM d, yyyy", Locale.US);
DateTimeFormatter de = DateTimeFormatter.ofPattern("MMMM d, yyyy", Locale.GERMANY);
System.out.println(fecha.format(us)); // October 5, 2026
System.out.println(fecha.format(de)); // Oktober 5, 2026

DateTimeFormatter fmt = DateTimeFormatter.ofPattern("d 'de' MMMM 'de' yyyy", Locale.of("es", "CL"));
LocalDate original = LocalDate.of(2026, 10, 5);
String texto = original.format(fmt); // 5 de octubre de 2026
LocalDate reconstruida = LocalDate.parse(texto, fmt);
System.out.println(reconstruida.equals(original)); // true
